  -- 01. Introducción al curso: el químico farmacéutico frente a la farmacología del SNC
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Un medicamento que llega al cerebro","texto":"Un paciente con epilepsia recibe un antiepiléptico que interactúa con su anticoagulante. La farmacología del SNC no termina en el receptor: incluye absorción, barrera hematoencefálica, interacciones y dispensación segura. El químico farmacéutico puede detectarlo."},"objetivos":["Reconocer el alcance de la farmacología del SNC.","Identificar el rol del QF.","Conocer el marco colombiano.","Aplicar el enfoque del curso."],"conceptos":[{"icono":"Network","termino":"SNC","definicion":"Cerebro y médula espinal; alta complejidad."},{"icono":"ShieldCheck","termino":"Control especial","definicion":"Medicamentos con regulación adicional."},{"icono":"Users","termino":"Rol del QF","definicion":"Dispensación, educación y seguimiento."},{"icono":"Activity","termino":"Neurofarmacología","definicion":"Estudio de los fármacos que actúan en el SNC."}],"secciones":[{"titulo":"Por qué este curso","parrafos":["Los fármacos del sistema nervioso central incluyen anestésicos, analgésicos, antiepilépticos, antiparkinsonianos, fármacos para las demencias, tratamientos de la migraña y de la esclerosis múltiple. Son medicamentos con márgenes terapéuticos estrechos, interacciones frecuentes y un alto impacto en la calidad de vida.","Este curso es neurológico, no psiquiátrico. La salud mental se aborda en otro curso. El enfoque es aplicado: mecanismo, farmacocinética, seguridad, interacciones y dispensación, con casos colombianos y herramientas para el seguimiento farmacoterapéutico."]},{"titulo":"El rol del QF","parrafos":["El QF participa en la dispensación informada, la revisión de interacciones, la educación sobre adherencia y efectos adversos, y la farmacovigilancia. En los medicamentos de control especial, verifica la normativa, la fórmula y el registro.","También detecta problemas relacionados con medicamentos, propone ajustes y acompaña la titulación. La farmacología del SNC exige leer la historia, el laboratorio y el contexto del paciente."]},{"titulo":"Marco colombiano","parrafos":["En Colombia, los medicamentos de control especial se regulan por el Fondo Nacional de Estupefacientes y las resoluciones del Ministerio de Salud. La dispensación exige fórmula, registro y trazabilidad. El QF es responsable de cumplir estos requisitos y de educar al paciente.","Las guías de práctica clínica, las fichas técnicas del INVIMA y la evidencia internacional complementan el marco normativo. La meta es un uso seguro, eficaz y accesible."]}],"errores":[{"error":"Ver solo la receta.","correccion":"La interacción está en la lista completa."},{"error":"Ignorar la normativa de control especial.","correccion":"Es obligatoria."},{"error":"No educar sobre adherencia.","correccion":"Afecta el control."}],"comprueba":[{"pregunta":"¿Qué áreas cubre el curso?","respuesta":"Anestesia, dolor, epilepsia y neurodegeneración."},{"pregunta":"¿Qué norma regula los controlados?","respuesta":"El FNE y las resoluciones del Ministerio."},{"pregunta":"¿Qué aporta el QF?","respuesta":"Dispensación segura, educación y seguimiento."}],"resumen":["El SNC concentra fármacos de alto riesgo.","El curso es neurológico, no psiquiátrico.","La normativa colombiana es parte del manejo.","Cada clase termina en un caso aplicado."],"referencias":[{"cita":"Ministerio de Salud y Protección Social. Fondo Nacional de Estupefacientes: normativa de medicamentos de control especial. Bogotá.","url":"https://www.minsalud.gov.co/"}],"imagenes":[{"ubicacion":"Introducción","descripcion":"Farmacéutico revisando medicación neurológica.","alt":"Introducción a la farmacología del SNC"}],"keywords":["farmacología snc","rol químico farmacéutico","control especial","neurología"],"mapa":{"centro":"Farmacología del SNC","ramas":[{"titulo":"Bases","icono":"Network","nodos":["Neurotransmisión","Barrera","Farmacocinética"]},{"titulo":"Dolor","icono":"Activity","nodos":["Opioides","AINE","Adyuvantes"]},{"titulo":"Epilepsia","icono":"Zap","nodos":["Clásicos","Nuevos","Interacciones"]},{"titulo":"Neurodegeneración","icono":"Timer","nodos":["Parkinson","Demencias","Migraña"]}]},"proceso":{"titulo":"Cómo estudiar el curso","intro":"","pasos":[{"titulo":"Contextualizar","detalle":"Leer el caso y la meta.","icono":"Target","evidencia":"Meta."},{"titulo":"Comprender","detalle":"Mecanismo y farmacocinética.","icono":"BookOpen","evidencia":"Notas."},{"titulo":"Aplicar","detalle":"Resolver el caso.","icono":"Workflow","evidencia":"Decisión."},{"titulo":"Verificar","detalle":"Comprobar lo aprendido.","icono":"ClipboardCheck","evidencia":"Resultado."},{"titulo":"Transferir","detalle":"Llevarlo a la práctica.","icono":"Repeat","evidencia":"Plan."}]},"caso":{"titulo":"Antiepiléptico e interacción","contexto":"Paciente con epilepsia que recibe un antiepiléptico inductor y un anticoagulante.","pregunta":"¿Qué revisa el QF?","opciones":[{"texto":"Solo la dosis del antiepiléptico.","correcta":false,"retro":"La interacción cambia el anticoagulante."},{"texto":"La interacción y el control del efecto.","correcta":true,"retro":"La seguridad es prioritaria."},{"texto":"Suspender todo sin consultar.","correcta":false,"retro":"Puede descompensar."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: el químico farmacéutico frente a la farmacología del SNC$t$ AND deleted_at IS NULL
