  -- 02. Neurotransmisores y receptores: dianas de los fármacos del SNC
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Cada fármaco tiene una diana","texto":"El GABA, el glutamato, la dopamina, la serotonina y los opioides son dianas de los fármacos del SNC. Conocer el receptor explica el efecto y el efecto adverso. La farmacología es un mapa de receptores."},"objetivos":["Reconocer los principales neurotransmisores.","Diferenciar receptores ionotrópicos y metabotrópicos.","Relacionar dianas y fármacos.","Aplicar el concepto de agonista y antagonista."],"conceptos":[{"icono":"Zap","termino":"Glutamato","definicion":"Principal excitador; receptores NMDA y AMPA."},{"icono":"ShieldCheck","termino":"GABA","definicion":"Principal inhibidor; receptor GABA-A."},{"icono":"Activity","termino":"Dopamina","definicion":"Movimiento, recompensa y motivación."},{"icono":"Network","termino":"Receptor","definicion":"Ionotrópico o metabotrópico."}],"secciones":[{"titulo":"Neurotransmisores","parrafos":["El glutamato es el principal neurotransmisor excitador y actúa sobre receptores NMDA, AMPA y metabotrópicos. El GABA es el principal inhibidor y actúa sobre receptores GABA-A y GABA-B. El equilibrio entre ambos es fundamental para la excitabilidad neuronal.","La dopamina regula el movimiento, la recompensa y la motivación; la serotonina, el ánimo, el sueño y la nocicepción; la noradrenalina, la atención y la respuesta al estrés. La acetilcolina participa en la memoria y el sistema autónomo. Los opioides endógenos modulan el dolor."]},{"titulo":"Receptores","parrafos":["Los receptores ionotrópicos son canales que se abren al unir el neurotransmisor y producen respuestas rápidas. Los metabotrópicos activan proteínas G y segundas vías, con respuestas más lentas y moduladoras. El tipo de receptor explica la latencia y la duración del efecto.","Los fármacos pueden ser agonistas completos, agonistas parciales, antagonistas o moduladores alostéricos. Las benzodiacepinas, por ejemplo, aumentan la apertura del canal GABA-A sin sustituir al GABA."]},{"titulo":"Dianas y fármacos","parrafos":["Los anestésicos inhalados y el propofol potencian el GABA-A; la ketamina bloquea el NMDA. Los antiepilépticos actúan sobre canales de sodio, calcio o GABA. Los antipsicóticos bloquean receptores dopaminérgicos D2. Los opioides activan receptores mu, kappa y delta.","El QF usa este mapa para predecir efectos adversos: el bloqueo muscarínico causa boca seca y estreñimiento; el bloqueo alfa-1, hipotensión; el bloqueo histamínico, sedación. La farmacología se vuelve predecible."]}],"errores":[{"error":"Confundir agonista con antagonista.","correccion":"El efecto puede ser opuesto."},{"error":"Ignorar los receptores secundarios.","correccion":"Explican los efectos adversos."},{"error":"No revisar la dosis.","correccion":"La respuesta depende de ella."}],"comprueba":[{"pregunta":"¿Cuál es el principal inhibidor?","respuesta":"El GABA."},{"pregunta":"¿Qué receptor bloquea la ketamina?","respuesta":"El NMDA."},{"pregunta":"¿Qué hace una benzodiacepina?","respuesta":"Potencia el GABA-A."}],"resumen":["Los neurotransmisores son las dianas.","Los receptores determinan la respuesta.","Los efectos adversos se predicen por el receptor.","El mapa guía la práctica."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Neurotransmisión","descripcion":"Neurotransmisores, receptores y fármacos.","alt":"Neurotransmisores y receptores del SNC"}],"keywords":["neurotransmisores","receptores snc","gaba","glutamato","dopamina"],"mapa":{"centro":"Neurotransmisión","ramas":[{"titulo":"Excitadores","icono":"Zap","nodos":["Glutamato","NMDA","AMPA"]},{"titulo":"Inhibidores","icono":"ShieldCheck","nodos":["GABA","GABA-A","Glicina"]},{"titulo":"Monoaminas","icono":"Activity","nodos":["Dopamina","Serotonina","Noradrenalina"]},{"titulo":"Otros","icono":"Network","nodos":["Acetilcolina","Opioides","Adenosina"]}]},"proceso":{"titulo":"Analizar una diana","intro":"","pasos":[{"titulo":"Neurotransmisor","detalle":"Excitador o inhibidor.","icono":"Zap","evidencia":"Mapa."},{"titulo":"Receptor","detalle":"Ionotrópico o metabotrópico.","icono":"Network","evidencia":"Ficha."},{"titulo":"Acción","detalle":"Agonista o antagonista.","icono":"Target","evidencia":"Mecanismo."},{"titulo":"Efecto","detalle":"Terapéutico y adverso.","icono":"Activity","evidencia":"Predicción."},{"titulo":"Aplicar","detalle":"Educación y seguimiento.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Benzodiacepina y GABA","contexto":"Paciente que recibe una benzodiacepina y presenta sedación.","pregunta":"¿Cuál es el mecanismo?","opciones":[{"texto":"Potenciación del GABA-A.","correcta":true,"retro":"Aumenta la inhibición."},{"texto":"Bloqueo del NMDA.","correcta":false,"retro":"Es el mecanismo de la ketamina."},{"texto":"Bloqueo dopaminérgico.","correcta":false,"retro":"Es el de los antipsicóticos."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Neurotransmisores y receptores: dianas de los fármacos del SNC$t$ AND deleted_at IS NULL
