  -- 03. Barrera hematoencefálica y farmacocinética en el SNC
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La barrera que decide","texto":"La dopamina no atraviesa la barrera hematoencefálica, pero la levodopa sí. Esa diferencia explica el tratamiento del Parkinson. La farmacocinética del SNC depende de la lipofilia, los transportadores y la barrera."},"objetivos":["Explicar la barrera hematoencefálica.","Reconocer los factores que permiten el paso al SNC.","Interpretar el papel de la gp-P.","Aplicar el concepto a fármacos concretos."],"conceptos":[{"icono":"ShieldCheck","termino":"BHE","definicion":"Barrera que regula el paso al cerebro."},{"icono":"Droplets","termino":"Lipofilia","definicion":"Facilita la difusión pasiva."},{"icono":"Network","termino":"gp-P","definicion":"Transportador de eflujo que expulsa fármacos."},{"icono":"Route","termino":"Transporte","definicion":"LAT1 para levodopa."}],"secciones":[{"titulo":"La barrera","parrafos":["La barrera hematoencefálica está formada por células endoteliales con uniones estrechas, astrocitos y pericitos. Regula el paso de sustancias y protege al cerebro. La inflamación, la isquemia y algunas enfermedades alteran su permeabilidad.","Los fármacos lipofílicos, pequeños y no cargados atraviesan con más facilidad. Los hidrofílicos necesitan transportadores. La gp-P, presente en la barrera, expulsa muchos fármacos y limita su concentración cerebral."]},{"titulo":"Aplicaciones","parrafos":["La dopamina no atraviesa la barrera, por eso se usa levodopa, que se transporta por el transportador de aminoácidos LAT1 y luego se convierte en dopamina. La loperamida es un opioide que no cruza la barrera en condiciones normales, lo que explica su efecto intestinal.","La naloxona cruza la barrera y revierte la depresión respiratoria. La naltrexona también. Los inhibidores de la gp-P pueden aumentar la exposición cerebral de algunos fármacos y sus efectos adversos."]},{"titulo":"Implicaciones clínicas","parrafos":["La edad, la enfermedad y la polifarmacia modifican la barrera y el metabolismo. Los efectos centrales, como la sedación o la confusión, son más frecuentes en adultos mayores. La revisión de la medicación debe considerar estos factores.","El QF educa sobre el paso al SNC y los efectos esperados. También revisa interacciones que afectan el transporte y el metabolismo, y detecta signos de toxicidad central."]}],"errores":[{"error":"Asumir que todo fármaco llega al cerebro.","correccion":"La BHE lo impide."},{"error":"Ignorar la gp-P.","correccion":"Limita la exposición."},{"error":"No considerar la edad.","correccion":"Más efectos centrales."}],"comprueba":[{"pregunta":"¿Qué transporta la levodopa?","respuesta":"El transportador LAT1."},{"pregunta":"¿Qué hace la gp-P?","respuesta":"Expulsa fármacos de la célula."},{"pregunta":"¿Por qué la loperamida no seda?","respuesta":"No cruza la barrera."}],"resumen":["La BHE regula el paso de fármacos.","La lipofilia y los transportadores importan.","La levodopa usa LAT1.","La gp-P limita la exposición cerebral."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"BHE","descripcion":"Barrera hematoencefálica y transportadores.","alt":"Barrera hematoencefálica y farmacocinética"}],"keywords":["barrera hematoencefálica","farmacocinética snc","gp-p","levodopa lat1"],"mapa":{"centro":"BHE","ramas":[{"titulo":"Estructura","icono":"ShieldCheck","nodos":["Uniones estrechas","Astrocitos","Pericitos"]},{"titulo":"Paso","icono":"Droplets","nodos":["Lipofilia","Tamaño","Carga"]},{"titulo":"Transporte","icono":"Route","nodos":["LAT1","gp-P","OATP"]},{"titulo":"Fármacos","icono":"Pill","nodos":["Levodopa","Loperamida","Naloxona"]}]},"proceso":{"titulo":"Analizar el paso al SNC","intro":"","pasos":[{"titulo":"Propiedad","detalle":"Lipofilia y carga.","icono":"Droplets","evidencia":"Ficha."},{"titulo":"Transporte","detalle":"LAT1 o gp-P.","icono":"Route","evidencia":"Mecanismo."},{"titulo":"Barrera","detalle":"Edad y enfermedad.","icono":"ShieldCheck","evidencia":"Contexto."},{"titulo":"Efecto","detalle":"Central o periférico.","icono":"Activity","evidencia":"Predicción."},{"titulo":"Revisar","detalle":"Interacciones y toxicidad.","icono":"AlertTriangle","evidencia":"Seguimiento."}]},"caso":{"titulo":"Levodopa y dopamina","contexto":"Paciente con Parkinson que pregunta por qué no se usa dopamina directamente.","pregunta":"¿Cuál es la explicación?","opciones":[{"texto":"La dopamina no atraviesa la barrera.","correcta":true,"retro":"La levodopa sí lo hace."},{"texto":"La dopamina es demasiado potente.","correcta":false,"retro":"El problema es la barrera."},{"texto":"La levodopa es un antagonista.","correcta":false,"retro":"Es un precursor."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Barrera hematoencefálica y farmacocinética en el SNC$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Barrera hematoencefálica y farmacocinética en el SNC$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
