  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. Anestésicos generales inhalados e intravenosos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El paciente que despierta tarde","texto":"Un paciente mayor tarda en despertar tras la anestesia. La edad, la polifarmacia y la liposolubilidad del anestésico influyen en la recuperación. Conocer los agentes permite anticipar y prevenir."},"objetivos":["Diferenciar los anestésicos generales.","Explicar sus mecanismos y efectos.","Reconocer los riesgos.","Aplicar la monitorización."],"conceptos":[{"icono":"Wind","termino":"Inhalado","definicion":"Sevoflurano, desflurano e isoflurano."},{"icono":"Syringe","termino":"Intravenoso","definicion":"Propofol, etomidato y ketamina."},{"icono":"Gauge","termino":"MAC","definicion":"Concentración alveolar mínima."},{"icono":"AlertTriangle","termino":"Hipertermia","definicion":"Riesgo con volátiles y succinilcolina."}],"secciones":[{"titulo":"Inhalados","parrafos":["Los anestésicos inhalados, como sevoflurano, desflurano e isoflurano, producen inconsciencia y amnesia. Su potencia se mide con la concentración alveolar mínima (MAC). El sevoflurano es útil en la inducción por su tolerancia; el desflurano tiene recuperación rápida; el isoflurano es económico.","Pueden causar hipotensión, depresión respiratoria, náuseas y vómito. El óxido nitroso se usa como coadyuvante. La hipertermia maligna es una reacción grave asociada a los volátiles y a la succinilcolina."]},{"titulo":"Intravenosos","parrafos":["El propofol potencia el GABA-A, produce hipnosis rápida y antiemesis; puede causar hipotensión y dolor en la inyección. El etomidato es estable hemodinámicamente pero puede suprimir la suprarrenal. La ketamina bloquea el NMDA, produce analgesia y disociación, y puede causar alucinaciones.","La dexmedetomidina es un agonista alfa-2 que produce sedación sin depresión respiratoria marcada. La elección depende del paciente, la cirugía y la hemodinamia."]},{"titulo":"Seguridad","parrafos":["La monitorización incluye saturación, capnografía, presión, ECG y temperatura. La prevención de náuseas y vómito, la hidratación y el control del dolor mejoran la recuperación. El QF revisa la medicación habitual y las interacciones.","La educación preanestésica incluye el ayuno, los medicamentos que se continúan o se suspenden y los signos de alarma. La seguridad anestésica es un trabajo de equipo."]}],"errores":[{"error":"No revisar la medicación crónica.","correccion":"Hay interacciones."},{"error":"Ignorar la temperatura.","correccion":"La hipertermia es grave."},{"error":"No prevenir náuseas.","correccion":"Afecta la recuperación."}],"comprueba":[{"pregunta":"¿Qué mide la MAC?","respuesta":"La potencia del inhalado."},{"pregunta":"¿Qué mecanismo tiene el propofol?","respuesta":"Potencia el GABA-A."},{"pregunta":"¿Qué fármaco revierte la hipertermia maligna?","respuesta":"El dantroleno."}],"resumen":["Inhalados e intravenosos tienen perfiles distintos.","La MAC mide la potencia.","La hipertermia maligna es una emergencia.","La revisión preanestésica es clave."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Anestesia","descripcion":"Anestésicos inhalados e intravenosos.","alt":"Anestésicos generales"}],"keywords":["anestésicos generales","propofol","sevoflurano","hipertermia maligna"],"mapa":{"centro":"Anestesia general","ramas":[{"titulo":"Inhalados","icono":"Wind","nodos":["Sevoflurano","Desflurano","Isoflurano"]},{"titulo":"Intravenosos","icono":"Syringe","nodos":["Propofol","Etomidato","Ketamina"]},{"titulo":"Mecanismo","icono":"Network","nodos":["GABA-A","NMDA","Canales"]},{"titulo":"Riesgos","icono":"AlertTriangle","nodos":["Hipotensión","PONV","Hipertermia"]}]},"proceso":{"titulo":"Revisión preanestésica","intro":"","pasos":[{"titulo":"Medicación","detalle":"Antihipertensivos y anticoagulantes.","icono":"ClipboardList","evidencia":"Lista."},{"titulo":"Riesgo","detalle":"Edad y comorbilidad.","icono":"Gauge","evidencia":"Evaluación."},{"titulo":"Elegir","detalle":"Inhalado o intravenoso.","icono":"Syringe","evidencia":"Plan."},{"titulo":"Monitorizar","detalle":"Signos y temperatura.","icono":"Activity","evidencia":"Registro."},{"titulo":"Recuperación","detalle":"Dolor y náuseas.","icono":"Users","evidencia":"Seguimiento."}]},"caso":{"titulo":"Rigidez e hipertermia","contexto":"Paciente que durante la anestesia con volátiles y succinilcolina presenta rigidez, hipercapnia e hipertermia.","pregunta":"¿Qué sospecha el equipo?","opciones":[{"texto":"Hipertermia maligna.","correcta":true,"retro":"Requiere dantroleno urgente."},{"texto":"Reacción alérgica leve.","correcta":false,"retro":"El cuadro es grave."},{"texto":"Hipotensión por propofol.","correcta":false,"retro":"No explica la rigidez."}]}}$j$::jsonb;
