  -- 05. Anestésicos locales: mecanismo, tipos y toxicidad
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El bloqueo que se vuelve sistémico","texto":"Una infiltración con bupivacaína produce convulsiones y arritmias. La toxicidad sistémica de los anestésicos locales es una emergencia. Conocer el mecanismo y el tratamiento salva vidas."},"objetivos":["Explicar el mecanismo de los anestésicos locales.","Diferenciar ésteres y amidas.","Reconocer la toxicidad.","Aplicar el tratamiento de la LAST."],"conceptos":[{"icono":"Zap","termino":"Canal de sodio","definicion":"Diana del anestésico local."},{"icono":"Pill","termino":"Amida","definicion":"Lidocaína, bupivacaína y ropivacaína."},{"icono":"AlertTriangle","termino":"LAST","definicion":"Toxicidad sistémica por anestésico local."},{"icono":"Droplets","termino":"Lípido","definicion":"Emulsión lipídica en el tratamiento."}],"secciones":[{"titulo":"Mecanismo y tipos","parrafos":["Los anestésicos locales bloquean los canales de sodio dependientes de voltaje y reducen la conducción nerviosa. Son bases débiles y su efecto depende del pH. Las amidas, como lidocaína, bupivacaína y ropivacaína, se metabolizan en el hígado; los ésteres, como la procaína, se hidrolizan por esterasas plasmáticas.","La afinidad por el canal, la liposolubilidad y la unión a proteínas determinan la potencia y la duración. La adrenalina prolonga el efecto y reduce la absorción sistémica en algunos casos."]},{"titulo":"Toxicidad","parrafos":["La toxicidad sistémica comienza con síntomas del SNC: adormecimiento perioral, mareo, tinnitus, agitación y convulsiones. Después aparecen arritmias y depresión miocárdica, especialmente con bupivacaína. La metahemoglobinemia es una complicación de la benzocaína y la prilocaína.","El tratamiento incluye detener la inyección, asegurar la vía aérea, administrar oxígeno, controlar las convulsiones y usar emulsión lipídica al 20 % en la toxicidad grave. La reanimación puede ser prolongada."]},{"titulo":"Prevención","parrafos":["La dosis máxima, la aspiración antes de inyectar y la monitorización reducen el riesgo. La elección del anestésico depende del procedimiento y del paciente. La alergia a las amidas es rara; a los ésteres, más frecuente.","El QF revisa la historia de alergias y la medicación. La educación del paciente sobre los síntomas y el cuidado posterior es parte de la seguridad."]}],"errores":[{"error":"Exceder la dosis máxima.","correccion":"Toxicidad sistémica."},{"error":"No aspirar antes de inyectar.","correccion":"Inyección intravascular."},{"error":"No reconocer la LAST.","correccion":"Retrasa el tratamiento."}],"comprueba":[{"pregunta":"¿Qué canal bloquean?","respuesta":"El canal de sodio."},{"pregunta":"¿Qué síntomas iniciales hay?","respuesta":"Perioral, tinnitus y agitación."},{"pregunta":"¿Qué se usa en la LAST grave?","respuesta":"Emulsión lipídica al 20 %."}],"resumen":["Los anestésicos locales bloquean el sodio.","Amidas y ésteres difieren en metabolismo.","La LAST es una emergencia.","La dosis y la aspiración previenen."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Anestésicos locales","descripcion":"Mecanismo, tipos y toxicidad.","alt":"Anestésicos locales"}],"keywords":["anestésicos locales","lidocaína","bupivacaína","last"],"mapa":{"centro":"Anestésicos locales","ramas":[{"titulo":"Mecanismo","icono":"Zap","nodos":["Na","Bloqueo","Fibra"]},{"titulo":"Tipos","icono":"Pill","nodos":["Éster","Amida","Duración"]},{"titulo":"Toxicidad","icono":"AlertTriangle","nodos":["SNC","Cardíaca","Metahemoglobina"]},{"titulo":"Tratamiento","icono":"Droplets","nodos":["Vía aérea","Lípido","Soporte"]}]},"proceso":{"titulo":"Checklist de anestésico local","intro":"","pasos":[{"titulo":"Tipo","detalle":"Éster o amida.","icono":"Pill","evidencia":"Ficha."},{"titulo":"Dosis","detalle":"Máxima por peso.","icono":"Calculator","evidencia":"Cálculo."},{"titulo":"Riesgo","detalle":"Cardíaco y alergias.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Toxicidad","detalle":"SNC y arritmias.","icono":"Zap","evidencia":"Vigilancia."},{"titulo":"Tratar","detalle":"Lípido y soporte.","icono":"Droplets","evidencia":"Protocolo."}]},"caso":{"titulo":"Bupivacaína y convulsión","contexto":"Paciente que tras una infiltración con bupivacaína presenta convulsiones y arritmia.","pregunta":"¿Qué hace el equipo?","opciones":[{"texto":"Suspender la inyección, soporte y emulsión lipídica.","correcta":true,"retro":"Es el manejo de la LAST."},{"texto":"Administrar más anestésico.","correcta":false,"retro":"Agrava la toxicidad."},{"texto":"Esperar sin monitorizar.","correcta":false,"retro":"Es una emergencia."}]}}$j$::jsonb;
