  -- 06. Caso clínico: toxicidad sistémica por anestésicos locales e hipertermia maligna
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Dos emergencias del quirófano","texto":"La toxicidad por anestésico local y la hipertermia maligna son emergencias con tratamiento específico. Reconocerlas y actuar rápido marca la diferencia. El caso integra mecanismo, clínica y manejo."},"objetivos":["Reconocer la LAST.","Aplicar el tratamiento con lípido.","Reconocer la hipertermia maligna.","Coordinar la respuesta del equipo."],"conceptos":[{"icono":"AlertTriangle","termino":"LAST","definicion":"Toxicidad sistémica por anestésico local."},{"icono":"Flame","termino":"Hipertermia","definicion":"Reacción grave a volátiles y succinilcolina."},{"icono":"Droplets","termino":"Lípido","definicion":"Antídoto de la LAST."},{"icono":"Syringe","termino":"Dantroleno","definicion":"Tratamiento de la hipertermia maligna."}],"secciones":[{"titulo":"Toxicidad por anestésico local","parrafos":["La LAST se presenta con síntomas neurológicos que progresan a convulsiones y, después, a arritmias y colapso cardiovascular. La bupivacaína es especialmente cardiotóxica. El manejo incluye detener la inyección, asegurar la vía aérea, oxigenar, controlar las convulsiones y administrar emulsión lipídica en los casos graves.","La emulsión lipídica actúa como un sumidero de lípidos y reduce la concentración del anestésico en el tejido cardíaco. La reanimación puede requerir tiempo prolongado. El equipo debe tener un protocolo disponible."]},{"titulo":"Hipertermia maligna","parrafos":["La hipertermia maligna es una reacción farmacogenética a los anestésicos volátiles y a la succinilcolina. Se manifiesta con hipercapnia, rigidez muscular, taquicardia e hipertermia. El tratamiento es el dantroleno, junto con enfriamiento, soporte y corrección de electrolitos.","La sospecha debe ser inmediata. La demora aumenta la mortalidad. El antecedente familiar y la evaluación preanestésica ayudan a prevenir."]},{"titulo":"Coordinación","parrafos":["El QF participa en la preparación de los medicamentos de emergencia, la disponibilidad del dantroleno y la emulsión lipídica, y la revisión de protocolos. También documenta el evento y participa en la farmacovigilancia.","La educación y el entrenamiento del equipo son parte de la seguridad. Las emergencias se manejan con roles claros y comunicación."]}],"errores":[{"error":"Retrasar el dantroleno.","correccion":"Aumenta la mortalidad."},{"error":"No tener protocolo de LAST.","correccion":"Retrasa el lípido."},{"error":"No documentar.","correccion":"Se pierde el aprendizaje."}],"comprueba":[{"pregunta":"¿Qué fármaco trata la hipertermia maligna?","respuesta":"El dantroleno."},{"pregunta":"¿Qué se usa en la LAST grave?","respuesta":"Emulsión lipídica."},{"pregunta":"¿Qué fármacos desencadenan la hipertermia?","respuesta":"Volátiles y succinilcolina."}],"resumen":["La LAST y la hipertermia son emergencias.","El tratamiento es específico y urgente.","La preparación del equipo salva vidas.","La documentación cierra el ciclo."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Protocolo de LAST e hipertermia maligna.","alt":"Toxicidad por anestésicos e hipertermia maligna"}],"keywords":["last","hipertermia maligna","emulsión lipídica","dantroleno"],"mapa":{"centro":"Emergencias","ramas":[{"titulo":"LAST","icono":"AlertTriangle","nodos":["Convulsión","Arritmia","Lípido"]},{"titulo":"Hipertermia","icono":"Flame","nodos":["Rigidez","Hipercapnia","Dantroleno"]},{"titulo":"Soporte","icono":"Activity","nodos":["Vía aérea","Oxígeno","Monitor"]},{"titulo":"Prevención","icono":"ShieldCheck","nodos":["Dosis","Historia","Protocolo"]}]},"proceso":{"titulo":"Responder a la emergencia","intro":"","pasos":[{"titulo":"Reconocer","detalle":"Signos y contexto.","icono":"AlertTriangle","evidencia":"Clínica."},{"titulo":"Detener","detalle":"Suspender el fármaco.","icono":"XCircle","evidencia":"Acción."},{"titulo":"Soporte","detalle":"Vía aérea y oxígeno.","icono":"Activity","evidencia":"Monitor."},{"titulo":"Antídoto","detalle":"Lípido o dantroleno.","icono":"Syringe","evidencia":"Protocolo."},{"titulo":"Documentar","detalle":"Reporte y análisis.","icono":"FileCheck","evidencia":"Registro."}]},"caso":{"titulo":"Rigidez e hipercapnia","contexto":"Paciente anestesiado con sevoflurano y succinilcolina que presenta rigidez, hipercapnia y fiebre.","pregunta":"¿Qué sospecha el equipo?","opciones":[{"texto":"Hipertermia maligna.","correcta":true,"retro":"Requiere dantroleno."},{"texto":"LAST.","correcta":false,"retro":"El contexto es otro."},{"texto":"Reacción alérgica.","correcta":false,"retro":"No explica la rigidez."}]}}$j$::jsonb;
