  -- 07. Introducción a la unidad: fisiopatología del dolor y analgesia
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El dolor no es solo una señal","texto":"El dolor tiene componentes sensoriales, emocionales y sociales. Su tratamiento combina fármacos con mecanismos distintos. Entender la vía nociceptiva permite elegir la analgesia y evitar el sufrimiento."},"objetivos":["Describir la vía nociceptiva.","Diferenciar dolor nociceptivo y neuropático.","Aplicar la analgesia multimodal.","Reconocer los objetivos del tratamiento."],"conceptos":[{"icono":"Zap","termino":"Nocicepción","definicion":"Transducción, transmisión y percepción."},{"icono":"Network","termino":"Modulación","definicion":"Vías descendentes y locales."},{"icono":"Pill","termino":"Multimodal","definicion":"Varios mecanismos a la vez."},{"icono":"Activity","termino":"Neuropático","definicion":"Dolor por lesión del sistema nervioso."}],"secciones":[{"titulo":"Vía nociceptiva","parrafos":["La nocicepción comienza con la activación de nociceptores periféricos, sigue con la transmisión por la médula espinal y termina en la percepción cerebral. Las vías descendentes modulan la señal y pueden amplificarla o inhibirla. La inflamación y la lesión nerviosa alteran este sistema.","El dolor nociceptivo responde a AINE y opioides. El neuropático responde a antidepresivos, anticonvulsivos y otros adyuvantes. El dolor mixto requiere combinar mecanismos."]},{"titulo":"Analgesia multimodal","parrafos":["La analgesia multimodal combina fármacos con mecanismos distintos para mejorar el alivio y reducir los efectos adversos. Por ejemplo, paracetamol, un AINE y un opioide en dosis bajas. La elección depende del tipo de dolor, la comorbilidad y el contexto.","La escalera analgésica de la OMS sigue siendo una guía, pero el enfoque moderno es mecanístico. El dolor oncológico y el postoperatorio requieren planes específicos."]},{"titulo":"Objetivos","parrafos":["El objetivo no siempre es el dolor cero: es mejorar la función y la calidad de vida con la menor toxicidad. La evaluación incluye intensidad, localización, características y respuesta al tratamiento.","El QF revisa la adherencia, las interacciones y los efectos adversos. La educación sobre el uso correcto y la prevención del estreñimiento por opioides es parte del manejo."]}],"errores":[{"error":"Tratar todo dolor igual.","correccion":"El mecanismo importa."},{"error":"No prevenir el estreñimiento.","correccion":"Es frecuente con opioides."},{"error":"Buscar siempre dolor cero.","correccion":"La función es la meta."}],"comprueba":[{"pregunta":"¿Cuáles son las fases de la nocicepción?","respuesta":"Transducción, transmisión y percepción."},{"pregunta":"¿Qué fármacos tratan el dolor neuropático?","respuesta":"Adyuvantes como gabapentina."},{"pregunta":"¿Qué es la analgesia multimodal?","respuesta":"Combinar mecanismos distintos."}],"resumen":["El dolor tiene una vía compleja.","Nociceptivo y neuropático difieren.","La analgesia multimodal es la base.","La meta es función y calidad de vida."],"referencias":[{"cita":"Organización Mundial de la Salud. Directrices sobre el tratamiento farmacológico del dolor persistente en niños con enfermedades médicas. Ginebra: OMS.","url":"https://www.who.int/"}],"imagenes":[{"ubicacion":"Unidad 2","descripcion":"Vía nociceptiva y dianas analgésicas.","alt":"Fisiopatología del dolor"}],"keywords":["fisiopatología dolor","nocicepción","dolor neuropático","analgesia multimodal"],"mapa":{"centro":"Dolor","ramas":[{"titulo":"Vía","icono":"Zap","nodos":["Nociceptor","Médula","Cerebro"]},{"titulo":"Tipos","icono":"Activity","nodos":["Nociceptivo","Neuropático","Mixto"]},{"titulo":"Fármacos","icono":"Pill","nodos":["AINE","Opioides","Adyuvantes"]},{"titulo":"Objetivos","icono":"Target","nodos":["Alivio","Función","Calidad"]}]},"proceso":{"titulo":"Evaluar el dolor","intro":"","pasos":[{"titulo":"Caracterizar","detalle":"Tipo e intensidad.","icono":"ClipboardList","evidencia":"Escala."},{"titulo":"Mecanismo","detalle":"Nociceptivo o neuropático.","icono":"Search","evidencia":"Juicio."},{"titulo":"Elegir","detalle":"Fármacos y combinación.","icono":"Pill","evidencia":"Plan."},{"titulo":"Revisar","detalle":"Efecto y toxicidad.","icono":"Activity","evidencia":"Seguimiento."},{"titulo":"Educar","detalle":"Uso y prevención.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Dolor neuropático","contexto":"Paciente con dolor quemante y hormigueo tras una lesión nerviosa.","pregunta":"¿Qué tratamiento es más adecuado?","opciones":[{"texto":"Un adyuvante como gabapentina o antidepresivo.","correcta":true,"retro":"El dolor neuropático responde a adyuvantes."},{"texto":"Solo AINE.","correcta":false,"retro":"No es el mecanismo principal."},{"texto":"Solo opioide.","correcta":false,"retro":"No es la primera elección."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: fisiopatología del dolor y analgesia$t$ AND deleted_at IS NULL
