  -- 08. Receptores opioides, agonistas y agonistas parciales
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"El receptor mu y la respiración","texto":"La activación del receptor mu produce analgesia, pero también depresión respiratoria y estreñimiento. Conocer los receptores explica por qué los opioides alivian y por qué pueden ser peligrosos."},"objetivos":["Diferenciar los receptores opioides.","Clasificar los agonistas.","Reconocer los efectos adversos.","Aplicar el concepto de agonista parcial."],"conceptos":[{"icono":"Target","termino":"Mu","definicion":"Analgesia, depresión respiratoria y euforia."},{"icono":"Activity","termino":"Kappa","definicion":"Analgesia y efectos disfóricos."},{"icono":"ShieldCheck","termino":"Parcial","definicion":"Buprenorfina; efecto techo respiratorio."},{"icono":"Network","termino":"Delta","definicion":"Modulación del dolor y el ánimo."}],"secciones":[{"titulo":"Receptores","parrafos":["Los receptores opioides mu, kappa y delta son metabotrópicos y modulan la transmisión del dolor. El mu es el principal responsable de la analgesia, la depresión respiratoria, la euforia y la dependencia. El kappa produce analgesia y efectos disfóricos. El delta modula el dolor y el ánimo.","Los opioides endógenos, como las endorfinas, actúan sobre estos receptores. Los fármacos exógenos reproducen y amplifican sus efectos."]},{"titulo":"Agonistas","parrafos":["La morfina, la oxicodona, la hidromorfona y el fentanilo son agonistas mu. El tramadol y el tapentadol tienen mecanismos mixtos. La codeína es un profármaco que requiere CYP2D6 para convertirse en morfina. La buprenorfina es un agonista parcial con alta afinidad y efecto techo en la depresión respiratoria.","Los agonistas parciales pueden precipitar abstinencia en pacientes dependientes. La elección depende del dolor, la vía, la duración y el perfil del paciente."]},{"titulo":"Efectos adversos","parrafos":["Los efectos adversos incluyen estreñimiento, náuseas, somnolencia, prurito, retención urinaria y depresión respiratoria. La tolerancia se desarrolla para algunos efectos, pero no para el estreñimiento. La prevención del estreñimiento es obligatoria al iniciar opioides.","La depresión respiratoria es el efecto más grave. El riesgo aumenta con dosis altas, combinación con benzodiacepinas, alcohol, apnea del sueño y enfermedad renal. La educación y la monitorización reducen el riesgo."]}],"errores":[{"error":"No prevenir el estreñimiento.","correccion":"Es universal."},{"error":"Combinar con benzodiacepinas sin control.","correccion":"Depresión respiratoria."},{"error":"Ignorar el CYP2D6.","correccion":"Codeína y tramadol."}],"comprueba":[{"pregunta":"¿Qué receptor media la depresión respiratoria?","respuesta":"El mu."},{"pregunta":"¿Qué opioide es parcial?","respuesta":"La buprenorfina."},{"pregunta":"¿Qué efecto no desarrolla tolerancia?","respuesta":"El estreñimiento."}],"resumen":["Los receptores opioides explican los efectos.","La buprenorfina es parcial.","El estreñimiento requiere prevención.","La depresión respiratoria es el riesgo grave."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Opioides","descripcion":"Receptores y efectos de los opioides.","alt":"Receptores opioides"}],"keywords":["receptores opioides","morfina","buprenorfina","depresión respiratoria"],"mapa":{"centro":"Opioides","ramas":[{"titulo":"Receptores","icono":"Target","nodos":["Mu","Kappa","Delta"]},{"titulo":"Agonistas","icono":"Pill","nodos":["Morfina","Fentanilo","Tramadol"]},{"titulo":"Parciales","icono":"ShieldCheck","nodos":["Buprenorfina","Techo"]},{"titulo":"Efectos","icono":"AlertTriangle","nodos":["Respiración","Constipación","Euforia"]}]},"proceso":{"titulo":"Elegir un opioide","intro":"","pasos":[{"titulo":"Dolor","detalle":"Intensidad y tipo.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Receptor","detalle":"Agonista o parcial.","icono":"Target","evidencia":"Mecanismo."},{"titulo":"Vía","detalle":"Oral, IV o transdérmica.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Riesgo","detalle":"Respiratorio y renal.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Educar","detalle":"Estreñimiento y alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Buprenorfina en dependencia","contexto":"Paciente con dependencia a opioides que recibe buprenorfina.","pregunta":"¿Qué riesgo existe?","opciones":[{"texto":"Precipitar abstinencia.","correcta":true,"retro":"Es un agonista parcial."},{"texto":"Depresión respiratoria grave.","correcta":false,"retro":"Tiene efecto techo."},{"texto":"Ninguno.","correcta":false,"retro":"Hay riesgo de abstinencia."}]}}$j$::jsonb;
