  -- 09. Farmacocinética de los opioides y particularidades por molécula
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La morfina que se acumula en el riñón","texto":"Un paciente con enfermedad renal recibe morfina y presenta somnolencia y depresión respiratoria. Los metabolitos se acumulan. La elección de la molécula y el ajuste renal son parte de la seguridad."},"objetivos":["Comparar la farmacocinética de los opioides.","Aplicar el ajuste renal.","Reconocer las interacciones.","Realizar una rotación segura."],"conceptos":[{"icono":"Droplets","termino":"Renal","definicion":"La morfina acumula metabolitos activos."},{"icono":"Database","termino":"CYP","definicion":"Metabolismo variable entre opioides."},{"icono":"Calculator","termino":"Equivalencia","definicion":"Conversión entre opioides."},{"icono":"Repeat","termino":"Rotación","definicion":"Cambio por efecto o toxicidad."}],"secciones":[{"titulo":"Metabolismo","parrafos":["La morfina se metaboliza por glucuronidación y produce morfina-6-glucurónido, activo, que se acumula en la enfermedad renal. El fentanilo se metaboliza por CYP3A4 y tiene una vida media corta por vía intravenosa. La oxicodona depende de CYP3A4 y CYP2D6. El tramadol y la codeína requieren CYP2D6 para su efecto.","Las variantes genéticas del CYP2D6 pueden producir falta de analgesia o toxicidad. Las interacciones con inhibidores o inductores modifican la exposición."]},{"titulo":"Ajuste y rotación","parrafos":["En la enfermedad renal se evitan la morfina y la codeína; se prefieren fentanilo, hidromorfona o metadona con precaución. La rotación de opioides se usa cuando hay falta de eficacia o efectos adversos. Se calcula la dosis equianalgésica y se reduce un 25-50 % por tolerancia incompleta.","La rotación requiere seguimiento estrecho. La dosis se titula según el dolor y los efectos adversos. La educación del paciente y la familia es esencial."]},{"titulo":"Interacciones y seguridad","parrafos":["Los inhibidores del CYP3A4, como los azoles y los macrólidos, aumentan la exposición al fentanilo y a la oxicodona. Los inductores la reducen. La combinación con benzodiacepinas, alcohol o gabapentinoides aumenta el riesgo de depresión respiratoria.","El QF revisa la lista completa, la función renal y hepática, y los signos de toxicidad. La documentación de la rotación y de la educación es parte de la dispensación segura."]}],"errores":[{"error":"Usar morfina en ERC avanzada.","correccion":"Acumula metabolitos activos."},{"error":"Rotar sin calcular equivalencia.","correccion":"Riesgo de toxicidad o dolor."},{"error":"No revisar inhibidores del CYP3A4.","correccion":"Aumentan la exposición."}],"comprueba":[{"pregunta":"¿Qué opioide se acumula en ERC?","respuesta":"La morfina."},{"pregunta":"¿Qué enzima metaboliza el fentanilo?","respuesta":"CYP3A4."},{"pregunta":"¿Cómo se rota?","respuesta":"Con dosis equianalgésica y reducción inicial."}],"resumen":["La farmacocinética varía entre opioides.","La morfina se acumula en ERC.","La rotación exige cálculo y seguimiento.","Las interacciones modifican la exposición."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Farmacocinética","descripcion":"Metabolismo y rotación de opioides.","alt":"Farmacocinética de los opioides"}],"keywords":["farmacocinética opioides","morfina erc","rotación opioides","fentanilo cyp3a4"],"mapa":{"centro":"Farmacocinética","ramas":[{"titulo":"Morfina","icono":"Pill","nodos":["Glucuronidación","M6G","Renal"]},{"titulo":"Fentanilo","icono":"Syringe","nodos":["CYP3A4","Transdérmico","Rápido"]},{"titulo":"Tramadol","icono":"Database","nodos":["CYP2D6","Serotonina","Convulsión"]},{"titulo":"Rotación","icono":"Calculator","nodos":["Equivalencia","Reevaluar","Titular"]}]},"proceso":{"titulo":"Rotar un opioide","intro":"","pasos":[{"titulo":"Calcular","detalle":"Dosis equianalgésica.","icono":"Calculator","evidencia":"Tabla."},{"titulo":"Ajustar","detalle":"Reducir por tolerancia.","icono":"Settings","evidencia":"Cálculo."},{"titulo":"Elegir","detalle":"Molécula y vía.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Monitorizar","detalle":"Dolor y toxicidad.","icono":"Activity","evidencia":"Seguimiento."},{"titulo":"Educar","detalle":"Rescate y alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Morfina en ERC","contexto":"Paciente con enfermedad renal avanzada que recibe morfina y presenta somnolencia.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Mantener la morfina.","correcta":false,"retro":"Los metabolitos se acumulan."},{"texto":"Alertar y proponer un opioide con menor acumulación.","correcta":true,"retro":"Evita la toxicidad."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
