  -- 10. Antagonistas opioides: naloxona, naltrexona y antagonistas periféricos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La naloxona que despierta","texto":"Un paciente con depresión respiratoria por opioides mejora con naloxona, pero la dosis debe titularse. Revertir por completo puede causar dolor intenso y abstinencia. La clave es recuperar la respiración, no despertar al paciente."},"objetivos":["Diferenciar los antagonistas.","Aplicar la naloxona con titulación.","Reconocer la naltrexona y los periféricos.","Educar sobre el riesgo."],"conceptos":[{"icono":"Syringe","termino":"Naloxona","definicion":"Antagonista competitivo de acción corta."},{"icono":"ShieldCheck","termino":"Naltrexona","definicion":"Antagonista de acción prolongada."},{"icono":"Droplets","termino":"Periférico","definicion":"Metilnaltrexona para constipación."},{"icono":"AlertTriangle","termino":"Abstinencia","definicion":"Riesgo al revertir en dependientes."}],"secciones":[{"titulo":"Naloxona","parrafos":["La naloxona es un antagonista competitivo de los receptores opioides. Se usa en la depresión respiratoria por opioides. Se administra por vía intravenosa o intramuscular y se titula hasta recuperar la respiración, no hasta despertar por completo. En pacientes dependientes, la reversión total precipita abstinencia y dolor.","Su acción dura menos que la de muchos opioides, por lo que puede requerir repetición o infusión. La observación posterior es obligatoria. La naloxona también se usa en la intoxicación por buprenorfina y en otros escenarios."]},{"titulo":"Naltrexona y periféricos","parrafos":["La naltrexona es un antagonista oral de acción prolongada que se usa en el trastorno por consumo de alcohol y en la dependencia a opioides. Puede causar hepatotoxicidad y no se usa con opioides. Requiere una evaluación previa.","La metilnaltrexona y el alvimopan son antagonistas periféricos que no cruzan la barrera hematoencefálica y se usan para la constipación inducida por opioides. No revierten la analgesia central."]},{"titulo":"Educación y seguridad","parrafos":["El QF educa sobre el riesgo de sobredosis, la importancia de no combinar opioides con alcohol o benzodiacepinas y el acceso a naloxona en pacientes de riesgo. También revisa la adherencia y los signos de depresión respiratoria.","La naloxona es una herramienta de emergencia, no un tratamiento de la dependencia. La comunicación con el equipo y la familia es clave."]}],"errores":[{"error":"Revertir por completo.","correccion":"Abstinencia y dolor."},{"error":"No observar la renarcotización.","correccion":"La naloxona dura poco."},{"error":"Usar naltrexona con opioides.","correccion":"Precipita abstinencia."}],"comprueba":[{"pregunta":"¿Hasta dónde se titula la naloxona?","respuesta":"Hasta recuperar la respiración."},{"pregunta":"¿Qué antagonista es periférico?","respuesta":"La metilnaltrexona."},{"pregunta":"¿Qué riesgo tiene la reversión total?","respuesta":"Abstinencia y dolor."}],"resumen":["La naloxona revierte la depresión respiratoria.","Se titula y se observa.","La naltrexona es de acción prolongada.","Los periféricos tratan la constipación."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Antagonistas","descripcion":"Naloxona, naltrexona y antagonistas periféricos.","alt":"Antagonistas opioides"}],"keywords":["naloxona","naltrexona","metilnaltrexona","depresión respiratoria"],"mapa":{"centro":"Antagonistas","ramas":[{"titulo":"Naloxona","icono":"Syringe","nodos":["IV/IM","Corta","Titular"]},{"titulo":"Naltrexona","icono":"ShieldCheck","nodos":["Oral","Larga","Alcohol"]},{"titulo":"Periféricos","icono":"Droplets","nodos":["Metilnaltrexona","Constipación"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Abstinencia","Dolor","Renarcotización"]}]},"proceso":{"titulo":"Revertir la depresión","intro":"","pasos":[{"titulo":"Reconocer","detalle":"Respiración y conciencia.","icono":"AlertTriangle","evidencia":"Evaluación."},{"titulo":"Titular","detalle":"Naloxona hasta respirar.","icono":"Syringe","evidencia":"Respuesta."},{"titulo":"Observar","detalle":"Renarcotización.","icono":"Timer","evidencia":"Monitor."},{"titulo":"Educar","detalle":"Riesgo y prevención.","icono":"Users","evidencia":"Consejería."},{"titulo":"Documentar","detalle":"Evento y reporte.","icono":"FileCheck","evidencia":"Registro."}]},"caso":{"titulo":"Reversión total","contexto":"Paciente dependiente de opioides con depresión respiratoria que recibe naloxona hasta despertar.","pregunta":"¿Qué riesgo presenta?","opciones":[{"texto":"Abstinencia y dolor intenso.","correcta":true,"retro":"La reversión total los precipita."},{"texto":"Ninguno.","correcta":false,"retro":"La titulación es necesaria."},{"texto":"Hipertermia maligna.","correcta":false,"retro":"No es el contexto."}]}}$j$::jsonb;
